namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
                Ingredients = ["Baguette", "Tomatoes", "Fresh basil", "Garlic", "Olive oil", "Balsamic vinegar"],
                Steps = ["Slice and toast the baguette.", "Dice tomatoes and mix with basil, garlic, and olive oil.", "Spoon mixture onto toast and drizzle with balsamic."],
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers", CategorySlug = "appetizers",
                Ingredients = ["Button mushrooms", "Cream cheese", "Garlic", "Parmesan", "Breadcrumbs", "Parsley"],
                Steps = ["Remove stems and hollow out mushroom caps.", "Mix cream cheese, garlic, parmesan, and breadcrumbs.", "Fill caps and bake at 375°F for 20 minutes."],
                AverageRating = 4.2, RatingCount = 8
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper"],
                Steps = ["Cook spaghetti until al dente.", "Fry pancetta until crispy.", "Mix eggs and parmesan, toss with hot pasta and pancetta.", "Season generously with black pepper."],
                AverageRating = 4.8, RatingCount = 25
            },
            new Recipe
            {
                Id = 4, Title = "Chicken Tikka Masala", Category = "Main Courses", CategorySlug = "main-courses",
                Ingredients = ["Chicken breast", "Yogurt", "Tikka spice mix", "Onion", "Tomato sauce", "Cream", "Rice"],
                Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry the chicken pieces.", "Sauté onion, add tomato sauce and cream.", "Combine chicken with sauce and serve over rice."],
                AverageRating = 4.6, RatingCount = 18
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour"],
                Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar, fold in chocolate mixture and flour.", "Pour into greased ramekins and bake at 425°F for 12 minutes.", "Invert onto plates and serve immediately."],
                AverageRating = 4.9, RatingCount = 30
            },
            new Recipe
            {
                Id = 6, Title = "Tiramisu", Category = "Desserts", CategorySlug = "desserts",
                Ingredients = ["Ladyfinger biscuits", "Espresso", "Mascarpone", "Eggs", "Sugar", "Cocoa powder"],
                Steps = ["Brew espresso and let it cool.", "Whisk egg yolks with sugar, fold in mascarpone.", "Dip ladyfingers in espresso and layer with cream.", "Refrigerate for 4 hours and dust with cocoa before serving."],
                AverageRating = 4.7, RatingCount = 22
            }
        ];
        _nextId = 7;
    }

    public List<Recipe> GetByCategory(string categorySlug)
    {
        return _recipes.Where(r => r.CategorySlug == categorySlug).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        var recipe = GetById(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);

        var allRatings = _ratings[recipeId];
        recipe.AverageRating = Math.Round(allRatings.Average(), 1);
        recipe.RatingCount = allRatings.Count;
    }
}

@page "/recipes"
@page "/recipes/{CategorySlug}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeHub</PageTitle>

@if (string.IsNullOrEmpty(CategorySlug))
{
    <h1>All Categories</h1>
    <div class="row">
        <div class="col-md-4 mb-3">
            <a href="recipes/appetizers" class="text-decoration-none">
                <div class="card h-100">
                    <div class="card-body text-center">
                        <h3>🥗 Appetizers</h3>
                    </div>
                </div>
            </a>
        </div>
        <div class="col-md-4 mb-3">
            <a href="recipes/main-courses" class="text-decoration-none">
                <div class="card h-100">
                    <div class="card-body text-center">
                        <h3>🍝 Main Courses</h3>
                    </div>
                </div>
            </a>
        </div>
        <div class="col-md-4 mb-3">
            <a href="recipes/desserts" class="text-decoration-none">
                <div class="card h-100">
                    <div class="card-body text-center">
                        <h3>🍰 Desserts</h3>
                    </div>
                </div>
            </a>
        </div>
    </div>
}
else
{
    <h1>@CategoryDisplayName</h1>
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item active">@CategoryDisplayName</li>
        </ol>
    </nav>

    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategorySlug { get; set; }

    private List<Recipe> recipes = [];

    private string CategoryDisplayName => CategorySlug switch
    {
        "appetizers" => "Appetizers",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        _ => CategorySlug ?? "Recipes"
    };

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(CategorySlug))
        {
            recipes = RecipeService.GetByCategory(CategorySlug);
        }
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.CategorySlug">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @recipe.Category</p>

    <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />

    <h2 class="mt-4">Ingredients</h2>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="d-flex align-items-center gap-1">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-4 text-decoration-none"
                    @onclick="() => SubmitRating(star)"
                    title="Rate @star stars">
                @(star <= hoveredStar ? "★" : "☆")
            </button>
        }
        <span class="ms-3 text-muted">
            @CurrentRating / 5 (@RatingCount ratings)
        </span>
    </div>
    @if (submitted)
    {
        <p class="text-success mt-2 mb-0">Thanks for your rating!</p>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int hoveredStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        RecipeService.RateRecipe(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        hoveredStar = stars;
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.Category">
            <option value="">-- Select a category --</option>
            <option value="appetizers">Appetizers</option>
            <option value="main-courses">Main Courses</option>
            <option value="desserts">Desserts</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients"
                       placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="model.Steps"
                       placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Bake for 30 minutes" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(model.Title) ||
            string.IsNullOrWhiteSpace(model.Category) ||
            string.IsNullOrWhiteSpace(model.Ingredients) ||
            string.IsNullOrWhiteSpace(model.Steps))
        {
            return;
        }

        var categoryDisplayName = model.Category switch
        {
            "appetizers" => "Appetizers",
            "main-courses" => "Main Courses",
            "desserts" => "Desserts",
            _ => model.Category
        };

        var recipe = new Recipe
        {
            Title = model.Title,
            Category = categoryDisplayName,
            CategorySlug = model.Category,
            Ingredients = model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        successMessage = $"'{recipe.Title}' has been submitted successfully!";
        model = new();
    }

    private class RecipeFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string Ingredients { get; set; } = string.Empty;
        public string Steps { get; set; } = string.Empty;
    }
}

